'use strict';
(function(){
 const base=renderMission;let mode='lesson',frame=null;
 function sendVisibility(visible){frame?.contentWindow?.postMessage({type:'lunares-lesson-visibility',version:1,visible},location.origin);}
 renderMission=function(...args){sendVisibility(false);base.apply(this,args);frame=null;if(!journeyStarted||mission.step!==2||!RM.ready)return;const root=document.getElementById('gameContent');const oldTitle=root.querySelector('#gameStageTitle');if(oldTitle)oldTitle.id='realMissionDateTitle';
  const real=document.createElement('div');real.id='realDateMissionPanel';while(root.firstChild)real.append(root.firstChild);root.append(real);
  const section=document.createElement('section');section.className='full-window-lesson';section.innerHTML=`<div class="full-lesson-head"><div><span class="eyebrow">DECISIÓN 3 · HORAS Y DÍAS</span><h1 id="gameStageTitle" tabindex="-1">Descubrí cuándo iluminar y comunicar.</h1><p>El simulador completo de tu equipo y tu misión real, en dos pestañas.</p></div></div><div class="full-lesson-tabs" role="tablist" aria-label="Explorar el tiempo"><button id="openWindowLesson" role="tab" aria-controls="originalWindowLessonPanel">① Jugar con el tiempo</button><button id="openRealDateMission" role="tab" aria-controls="realDateMissionPanel">② Aplicar a mi misión</button></div><div id="originalWindowLessonPanel" role="tabpanel" aria-labelledby="openWindowLesson"><p class="lesson-model-note"><b>Entrenamiento:</b> base fija en Site01, horizonte ideal y energía ilustrativa. No usa las montañas ni la batería de tu rover; esos resultados están en «Aplicar a mi misión».</p><iframe class="full-window-player" title="Ventana de enlace: simulador completo del equipo" src="ventana-enlace/index.html?embedded=1" loading="eager"></iframe><div class="lesson-bottom"><span>Órbitas + perfil lunar + cielo + plan de transmisión · mové el reloj y pintá los bloques.</span><button id="windowLessonToReal">Comparar con mi terreno real →</button></div><p id="lessonApplyStatus" role="status"></p></div>`;
  root.prepend(section);frame=section.querySelector('iframe');frame.onload=()=>sendVisibility(mode==='lesson');real.setAttribute('role','tabpanel');real.setAttribute('aria-labelledby','openRealDateMission');
  const first=document.getElementById('openWindowLesson'),second=document.getElementById('openRealDateMission'),lesson=document.getElementById('originalWindowLessonPanel');
  function show(value){mode=value;const teaching=mode==='lesson';lesson.hidden=!teaching;real.hidden=teaching;first.setAttribute('aria-selected',String(teaching));second.setAttribute('aria-selected',String(!teaching));first.tabIndex=teaching?0:-1;second.tabIndex=teaching?-1:0;sendVisibility(teaching);if(teaching){guideClosed=true;setGuideBubble('comms','Mirá las cuatro vistas juntas.','Este juego usa un horizonte ideal. Mové el reloj, pintá tu plan y después comparalo con el relieve real de tu misión.');}else updateFloatingGuide();}
  first.onclick=()=>show('lesson');second.onclick=document.getElementById('windowLessonToReal').onclick=()=>show('real');for(const b of[first,second])b.onkeydown=e=>{if(e.key!=='ArrowLeft'&&e.key!=='ArrowRight')return;e.preventDefault();show(b===first?'real':'lesson');(b===first?second:first).focus();};show(mode);
 };
 window.addEventListener('message',e=>{if(!frame||e.origin!==location.origin||e.source!==frame.contentWindow||e.data?.type!=='lunares-window-lesson-date'||e.data.version!==1)return;const value=e.data.start;if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}T00:00$/.test(value))return;mode='real';if(!applyDateValue(value)){const status=document.getElementById('lessonApplyStatus');if(status)status.textContent='Ese inicio no tiene siete días completos en nuestro archivo NASA de 2025–2026.';}});
 window.addEventListener('hashchange',()=>{if(location.hash!=='#mission')sendVisibility(false);});
 const oldRestart=document.getElementById('restartMission').onclick;document.getElementById('restartMission').onclick=()=>{mode='lesson';oldRestart();};
 if(journeyStarted)renderMission();
})();
